#[test]
fn a_refused_origin_never_echoes_the_remote() {
    for raw in [
        "REDACTED",
        "ssh://deploy@example.test/o/r.git",
        "http://github.com/o/r.git",
        "remotes/origin.git",
        "REDACTED",
    ] {
        let error = Origin::parse(raw).optional().unwrap_err();
        assert!(
            error.to_string().contains("`origin` is not a hosted remote: "),
            "{error}"
        );
        assert!(error.to_string().contains("(use https://"), "{error}");
        for text in [error.to_string(), format!("{error:?}")] {
            for leak in ["REDACTED", "REDACTED", "deploy", "example.test", "github.com", "remotes/origin"] {
                assert!(!text.contains(leak), "{text}");
            }
        }
    }

